function normalizeButtonVariant(value) {
    const variant = stringOrEmpty(value);

    if (variant === '') {
        return 'btn--primary';
    }

    if (variant === 'primary' || variant === 'secondary' || variant === 'danger') {
        return 'btn--' + variant;
    }

    return variant;
}
